            ['tracking_number' => 22394050154005, 'charges' => 30.08],
            ['tracking_number' => 20231550177695, 'charges' => 14],
            ['tracking_number' => 14438350234357, 'charges' => 25.52],
            ['tracking_number' => 20220249896761, 'charges' => 16.9],
